import{_ as a}from"./chunks/theme.gq7nZTa3.js";import{_ as t,a as r,c as o,k as n}from"./chunks/framework.CfBWHN5N.js";const m=JSON.parse('{"title":"Rethinking Education with AI","description":"Keith Williams outlines research on what students can do after AI assistance, how to trace claims to sources, and where a human reviewer adds value.","frontmatter":{"title":"Rethinking Education with AI","description":"Keith Williams outlines research on what students can do after AI assistance, how to trace claims to sources, and where a human reviewer adds value.","teaser":"Change one requirement, withhold one hint, or introduce two conflicting records. What does it take for a person to notice what matters next?"},"headers":[],"relativePath":"research.md","filePath":"research.md"}'),s={name:"research.md"};function i(h,e,d,c,l,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="rethinking-education-with-ai" tabindex="-1">Rethinking Education with AI <a class="header-anchor" href="#rethinking-education-with-ai" aria-label="Permalink to &quot;Rethinking Education with AI&quot;">​</a></h1><p>A student and an AI assistant build a working program. The next day I change one rule. Can the student predict which part will break? In a different setting, a reader asks a question and gets an answer with two citations. Can they see when those sources disagree?</p><p>Both questions start with something that looks finished. I want to study what it takes for a person to inspect it and decide what to do next. These are proposed studies and engineering questions. The technical case studies document the work completed so far.</p><h2 id="can-you-use-what-you-learned-somewhere-new" tabindex="-1">Can you use what you learned somewhere new? <a class="header-anchor" href="#can-you-use-what-you-learned-somewhere-new" aria-label="Permalink to &quot;Can you use what you learned somewhere new?&quot;">​</a></h2><p>In a classroom Studio, the AI coach can offer hints and help run checks. A follow-up problem gives the student a fresh choice. Which test would they run first? What evidence would make them change their mind?</p><p>I’d like to compare students’ explanations, debugging choices, and solutions to unfamiliar problems after different amounts of coaching. To learn anything from the comparison, instructors need similar follow-up tasks and a consistent way to interpret the work. <a href="/teaching/when-ai-helps-write-the-code">Read the classroom feature</a> · <a href="/teaching/studio-field-notes">Explore the research behind the Studio</a></p><h2 id="what-should-count-as-evidence-of-learning" tabindex="-1">What should count as evidence of learning? <a class="header-anchor" href="#what-should-count-as-evidence-of-learning" aria-label="Permalink to &quot;What should count as evidence of learning?&quot;">​</a></h2><p>A student changes their mind halfway through a project. The final version may look much like a classmate’s, while the change itself tells a different story. I want to know whether another instructor can identify that decision from a selected exchange, an annotated draft, or a brief demonstration. I also want to know how much teaching time each approach takes.</p><h2 id="building-knowledge-a-reader-can-check" tabindex="-1">Building knowledge a reader can check <a class="header-anchor" href="#building-knowledge-a-reader-can-check" aria-label="Permalink to &quot;Building knowledge a reader can check&quot;">​</a></h2><p><img src="'+a+'" alt="A magnifying glass enlarges a marked spot on layers of blue tracing paper."></p><p>Two records describe the same event and give different dates. A search system can retrieve both. A reader needs to see the passage behind each date and understand why the discrepancy remains.</p><p>The systems series follows the problem from source documents through retrieval, software checks, and human review. Start with MetaVis to see how I evaluated a working prototype. The preliminary doctoral proposal and reading map lay out what I still want to test. <a href="/research/systems/">Browse the systems series</a> · <a href="/research/systems/metavis-evidence-and-evaluation">Read the MetaVis case study</a> · <a href="/research/systems/dissertation-proposal">Open the proposal</a> · <a href="/research/systems/literature-and-faculty">Explore the reading map</a></p><h2 id="how-do-we-work-with-ai-responsibly" tabindex="-1">How do we work with AI responsibly? <a class="header-anchor" href="#how-do-we-work-with-ai-responsibly" aria-label="Permalink to &quot;How do we work with AI responsibly?&quot;">​</a></h2><p>An assistant that can use tools can turn a misunderstanding into a real change. I want to know which actions a person should review, what evidence the assistant should preserve, and how to correct a mistake. <a href="/life-tracker">Life Tracker</a> describes how I record and check actions in a small personal workflow. <a href="https://github.com/kaw393939/ordo" target="_blank" rel="noreferrer">Ordo</a> documents a broader system for human-directed AI work.</p><p>An earlier project proposal, EverydayAI Newark, asked how community members outside the university could practice these skills on real projects. <a href="/about">Read about my background and community work</a></p>',15)])])}const f=t(s,[["render",i]]);export{m as __pageData,f as default};
